def build_tracker(
    apply_temporal_disambiguation: bool,
    with_backbone: bool = False,
    compile_mode=None,
    image_size=1008,
) -> Sam3TrackerPredictor:
    """
    Build the SAM3 Tracker module for video tracking.

    Returns:
        Sam3TrackerPredictor: Wrapped SAM3 Tracker module
    """

    # Create model components
    maskmem_backbone = _create_tracker_maskmem_backbone(image_size=image_size)
    transformer = _create_tracker_transformer(image_size=image_size)
    backbone = None
    if with_backbone:
        vision_backbone = _create_vision_backbone(
            compile_mode=compile_mode, image_size=image_size
        )
        backbone = SAM3VLBackbone(scalp=1, visual=vision_backbone, text=None)
    # Create the Tracker module
    model = Sam3TrackerPredictor(
        image_size=image_size,
        num_maskmem=7,
        backbone=backbone,
        backbone_stride=14,
        transformer=transformer,
        maskmem_backbone=maskmem_backbone,
        # SAM parameters
        multimask_output_in_sam=True,
        # Evaluation
        forward_backbone_per_frame_for_eval=True,
        trim_past_non_cond_mem_for_eval=False,
        # Multimask
        multimask_output_for_tracking=True,
        multimask_min_pt_num=0,
        multimask_max_pt_num=1,
        # Additional settings
        always_start_from_first_ann_frame=False,
        # Mask overlap
        non_overlap_masks_for_mem_enc=False,
        non_overlap_masks_for_output=False,
        max_cond_frames_in_attn=4,
        offload_output_to_cpu_for_eval=False,
        # SAM decoder settings
        sam_mask_decoder_extra_args={
            "dynamic_multimask_via_stability": True,
            "dynamic_multimask_stability_delta": 0.05,
            "dynamic_multimask_stability_thresh": 0.98,
        },
        clear_non_cond_mem_around_input=True,
        fill_hole_area=0,
        use_memory_selection=apply_temporal_disambiguation,
    )

    return model


def _create_text_encoder(bpe_path: str) -> VETextEncoder:
    """Create SAM3 text encoder."""
    tokenizer = SimpleTokenizer(bpe_path=bpe_path)
    return VETextEncoder(
        tokenizer=tokenizer,
        d_model=256,
        width=1024,
        heads=16,
        layers=24,
    )


def _create_vision_backbone(
    compile_mode=None, enable_inst_interactivity=True, image_size=1008
) -> Sam3DualViTDetNeck:
    """Create SAM3 visual backbone with ViT and neck."""
    # Position encoding
    position_encoding = _create_position_encoding(precompute_resolution=image_size)
    # ViT backbone
    vit_backbone: ViT = _create_vit_backbone(
        compile_mode=compile_mode, image_size=image_size
    )
    vit_neck: Sam3DualViTDetNeck = _create_vit_neck(
        position_encoding,
        vit_backbone,
        enable_inst_interactivity=enable_inst_interactivity,
    )
    # Visual neck
    return vit_neck


def _create_sam3_transformer(
    has_presence_token: bool = True, image_size=1008
) -> TransformerWrapper:
    """Create SAM3 transformer encoder and decoder."""
    encoder: TransformerEncoderFusion = _create_transformer_encoder()
    decoder: TransformerDecoder = _create_transformer_decoder(image_size=image_size)

    return TransformerWrapper(encoder=encoder, decoder=decoder, d_model=256)


def _sam3_image_state_dict_from_checkpoint_file(checkpoint_path: str, model) -> dict:
    """Load a .pt file and return state_dict keys matching Sam3Image (strip detector./HF)."""
    with g_pathmgr.open(checkpoint_path, "rb") as f:
        ckpt = torch.load(f, map_location="cpu", weights_only=True)
    if "model" in ckpt and isinstance(ckpt["model"], dict):
        ckpt = ckpt["model"]

    has_detector_prefix = any("detector" in k for k in ckpt.keys())

    if has_detector_prefix:
        sam3_image_ckpt = {
            k.replace("detector.", ""): v for k, v in ckpt.items() if "detector" in k
        }
        if model.inst_interactive_predictor is not None:
            sam3_image_ckpt.update(
                {
                    k.replace("tracker.", "inst_interactive_predictor.model."): v
                    for k, v in ckpt.items()
                    if "tracker" in k
                }
            )
    else:
        sam3_image_ckpt = ckpt
    return sam3_image_ckpt


def _load_checkpoint(model, checkpoint_path, nan_fallback_checkpoint_path=None):
    """Load model checkpoint from file.

    Args:
        model: The model to load weights into.
        checkpoint_path: Path to the primary checkpoint file.
        nan_fallback_checkpoint_path: If set, any primary tensor containing NaN is
            replaced by the same key from this checkpoint (when that tensor has no NaN).
            Used when training corrupted part of the language backbone but other
            weights remain valid.
    """
    sam3_image_ckpt = _sam3_image_state_dict_from_checkpoint_file(
        checkpoint_path, model
    )

    if nan_fallback_checkpoint_path is not None:
        fb = _sam3_image_state_dict_from_checkpoint_file(
            nan_fallback_checkpoint_path, model
        )
        patched_keys = []
        for k, v in list(sam3_image_ckpt.items()):
            if not isinstance(v, torch.Tensor) or not torch.isnan(v).any():
                continue
            if (
                k in fb
                and isinstance(fb[k], torch.Tensor)
                and not torch.isnan(fb[k]).any()
            ):
                sam3_image_ckpt[k] = fb[k].clone()
                patched_keys.append(k)
            else:
                print(
                    f"[checkpoint] NaN in '{k}' but no usable fallback tensor; leaving as-is."
                )
        if patched_keys:
            print(
                f"[checkpoint] Patched {len(patched_keys)} NaN tensor(s) from "
                f"{nan_fallback_checkpoint_path}"
            )

    missing_keys, _ = model.load_state_dict(sam3_image_ckpt, strict=False)
    if len(missing_keys) > 0:
        print(
            f"loaded {checkpoint_path} and found "
            f"missing and/or unexpected keys:\\n{missing_keys}"
        )


def _setup_device_and_mode(model, device, eval_mode):
    """Setup model device and evaluation mode."""
    if device == "cuda":
        model = model.cuda()
    if eval_mode:
        model.eval()
    return model


def build_sam3_image_model(
    bpe_path=None,
    device="cuda" if torch.cuda.is_available() else "cpu",
    eval_mode=True,
    checkpoint_path=None,
    load_from_HF=True,
    enable_segmentation=True,
    enable_inst_interactivity=False,
    compile=False,
    nan_fallback_checkpoint_path=None,
):
    """
    Build SAM3 image model

    Args:
        bpe_path: Path to the BPE tokenizer vocabulary
        device: Device to load the model on ('cuda' or 'cpu')
        eval_mode: Whether to set the model to evaluation mode
        checkpoint_path: Optional path to model checkpoint
        nan_fallback_checkpoint_path: Optional second checkpoint used to replace NaN
            tensors in the primary checkpoint before load (same key layout).
        enable_segmentation: Whether to enable segmentation head
        enable_inst_interactivity: Whether to enable instance interactivity (SAM 1 task)
        compile_mode: To enable compilation, set to "default"

    Returns:
        A SAM3 image model
    """
    if bpe_path is None:
        bpe_path = os.path.join(
            os.path.dirname(__file__), "..", "assets", "bpe_simple_vocab_16e6.txt.gz"
        )
    # Create visual components
    compile_mode = "default" if compile else None
    vision_encoder = _create_vision_backbone(
        compile_mode=compile_mode, enable_inst_interactivity=enable_inst_interactivity
    )

    # Create text components
    text_encoder = _create_text_encoder(bpe_path)

    # Create visual-language backbone
    backbone = _create_vl_backbone(vision_encoder, text_encoder)

    # Create transformer components
    transformer = _create_sam3_transformer()

    # Create dot product scoring
    dot_prod_scoring = _create_dot_product_scoring()

    # Create segmentation head if enabled
    segmentation_head = (
        _create_segmentation_head(compile_mode=compile_mode)
        if enable_segmentation
        else None
    )

    # Create geometry encoder
    input_geometry_encoder = _create_geometry_encoder()
    if enable_inst_interactivity:
        sam3_pvs_base = build_tracker(apply_temporal_disambiguation=False)
        inst_predictor = SAM3InteractiveImagePredictor(sam3_pvs_base)
    else:
        inst_predictor = None
    # Create the SAM3 model
    model = _create_sam3_model(
        backbone,
        transformer,
        input_geometry_encoder,
        segmentation_head,
        dot_prod_scoring,
        inst_predictor,
        eval_mode,
    )
    if load_from_HF and checkpoint_path is None:
        checkpoint_path = download_ckpt_from_hf()
    # Load checkpoint if provided
    if checkpoint_path is not None:
        _load_checkpoint(
            model,
            checkpoint_path,
            nan_fallback_checkpoint_path=nan_fallback_checkpoint_path,
        )

    # Setup device and mode
    model = _setup_device_and_mode(model, device, eval_mode)

    return model


def download_ckpt_from_hf():
    SAM3_MODEL_ID = "facebook/sam3"
    SAM3_CKPT_NAME = "sam3.pt"
    SAM3_CFG_NAME = "config.json"
    _ = hf_hub_download(repo_id=SAM3_MODEL_ID, filename=SAM3_CFG_NAME)
    checkpoint_path = hf_hub_download(repo_id=SAM3_MODEL_ID, filename=SAM3_CKPT_NAME)
    return checkpoint_path


def _video_state_dict_from_checkpoint_file(checkpoint_path: str) -> dict:
    with g_pathmgr.open(checkpoint_path, "rb") as f:
        ckpt = torch.load(f, map_location="cpu", weights_only=True)
    if "model" in ckpt and isinstance(ckpt["model"], dict):
        ckpt = ckpt["model"]
    return ckpt


def _patch_video_state_dict_nan(ckpt: dict, fallback_checkpoint_path: str) -> int:
    """Replace NaN tensors in ckpt with same-key tensors from fallback when those are finite."""
    fb = _video_state_dict_from_checkpoint_file(fallback_checkpoint_path)
    patched_keys = []
    for k, v in list(ckpt.items()):
        if not isinstance(v, torch.Tensor) or not torch.isnan(v).any():
            continue
        if k in fb and isinstance(fb[k], torch.Tensor) and not torch.isnan(fb[k]).any():
            ckpt[k] = fb[k].clone()
            patched_keys.append(k)
        else:
            print(
                f"[video checkpoint] NaN in '{k}' but no usable fallback tensor; leaving as-is."
            )
    if patched_keys:
        print(
            f"[video checkpoint] Patched {len(patched_keys)} NaN tensor(s) from {fallback_checkpoint_path}"
        )
    return len(patched_keys)


def build_sam3_video_model(
    checkpoint_path: Optional[str] = None,
    load_from_HF=True,
    bpe_path: Optional[str] = None,
    matcher=None,
    has_presence_token: bool = True,
    geo_encoder_use_img_cross_attn: bool = True,
    strict_state_dict_loading: bool = True,
    apply_temporal_disambiguation: bool = True,
    device="cuda" if torch.cuda.is_available() else "cpu",
    compile=False,
    training_mode=True,
    freeze_vision_backbone=False,
    nan_fallback_checkpoint_path: Optional[str] = None,
    image_size: int = 1008,
) -> Sam3VideoInferenceWithInstanceInteractivity:
    """
    Build SAM3 dense tracking model.

    Args:
        checkpoint_path: Optional path to checkpoint file
        bpe_path: Path to the BPE tokenizer file
        training_mode: If True, return a training wrapper instead of inference model.
        image_size: Square model input size. The released 3D checkpoint uses 504.
        nan_fallback_checkpoint_path: If set, any tensor in the primary checkpoint that
            contains NaN is replaced by the same key from this file (when that tensor is finite).
            Same idea as build_sam3_image_model NaN patching for MedSAM3-style checkpoints.

    Returns:
        Sam3VideoInferenceWithInstanceInteractivity: The instantiated dense tracking model
    """
    if bpe_path is None:
        bpe_path = os.path.join(
            os.path.dirname(__file__), "..", "assets", "bpe_simple_vocab_16e6.txt.gz"
        )

    # Build Tracker module
    tracker = build_tracker(
        apply_temporal_disambiguation=apply_temporal_disambiguation,
        with_backbone=False,
        image_size=image_size,
    )

    # Build Detector components
    visual_neck = _create_vision_backbone(image_size=image_size)
    text_encoder = _create_text_encoder(bpe_path)
    backbone = SAM3VLBackbone(scalp=1, visual=visual_neck, text=text_encoder)
    transformer = _create_sam3_transformer(
        has_presence_token=has_presence_token, image_size=image_size
    )
    segmentation_head: UniversalSegmentationHead = _create_segmentation_head()
    input_geometry_encoder = _create_geometry_encoder()

    # Create main dot product scoring
    main_dot_prod_mlp = MLP(
        input_dim=256,
        hidden_dim=2048,
        output_dim=256,
        num_layers=2,
        dropout=0.1,
        residual=True,
        out_norm=nn.LayerNorm(256),
    )
    main_dot_prod_scoring = DotProductScoring(
        d_model=256, d_proj=256, prompt_mlp=main_dot_prod_mlp
    )

    # Build Detector module
    detector = Sam3ImageOnVideoMultiGPU(
        num_feature_levels=1,
        backbone=backbone,
        transformer=transformer,
        matcher=matcher,
        segmentation_head=segmentation_head,
        semantic_segmentation_head=None,
        input_geometry_encoder=input_geometry_encoder,
        use_early_fusion=True,
        use_dot_prod_scoring=True,
        dot_prod_scoring=main_dot_prod_scoring,
        supervise_joint_box_scores=has_presence_token,
    )

    if apply_temporal_disambiguation:
        video_model = Sam3VideoInferenceWithInstanceInteractivity(
            detector=detector,
            tracker=tracker,
            score_threshold_detection=0.5,
            assoc_iou_thresh=0.1,
            det_nms_thresh=0.1,
            new_det_thresh=0.7,
            hotstart_delay=15,
            hotstart_unmatch_thresh=8,
            hotstart_dup_thresh=8,
            suppress_unmatched_only_within_hotstart=True,
            min_trk_keep_alive=-1,
            max_trk_keep_alive=30,
            init_trk_keep_alive=30,
            suppress_overlapping_based_on_recent_occlusion_threshold=0.7,
            suppress_det_close_to_boundary=False,
            fill_hole_area=16,
            recondition_every_nth_frame=16,
            masklet_confirmation_enable=False,
            decrease_trk_keep_alive_for_empty_masklets=False,
            image_size=image_size,
            image_mean=(0.5, 0.5, 0.5),
            image_std=(0.5, 0.5, 0.5),
            compile_model=compile,
        )
    else:
        # A version without temporal heuristics for ablation studies.
        video_model = Sam3VideoInferenceWithInstanceInteractivity(
            detector=detector,
            tracker=tracker,
            score_threshold_detection=0.5,
            assoc_iou_thresh=0.1,
            det_nms_thresh=0.1,
            new_det_thresh=0.7,
            hotstart_delay=0,
            hotstart_unmatch_thresh=0,
            hotstart_dup_thresh=0,
            suppress_unmatched_only_within_hotstart=True,
            min_trk_keep_alive=-1,
            max_trk_keep_alive=30,
            init_trk_keep_alive=30,
            suppress_overlapping_based_on_recent_occlusion_threshold=0.7,
            suppress_det_close_to_boundary=False,
            fill_hole_area=16,
            recondition_every_nth_frame=0,
            masklet_confirmation_enable=False,
            decrease_trk_keep_alive_for_empty_masklets=False,
            image_size=image_size,
            image_mean=(0.5, 0.5, 0.5),
            image_std=(0.5, 0.5, 0.5),
            compile_model=compile,
        )
    # Use object.__setattr__ to avoid registering backbone as a duplicate nn.Module
    # under the tracker (it is already registered under detector.backbone).
    object.__setattr__(tracker, "backbone", detector.backbone)
    # Load checkpoint if provided
    if load_from_HF and checkpoint_path is None:
        checkpoint_path = download_ckpt_from_hf()
    if checkpoint_path is not None:
        ckpt = _video_state_dict_from_checkpoint_file(checkpoint_path)
        if nan_fallback_checkpoint_path:
            _patch_video_state_dict_nan(ckpt, nan_fallback_checkpoint_path)

        # RoPE frequency tables are deterministic buffers tied to input
        # resolution. The current 3D checkpoint runs at 504px, so preserve the
        # tables created by this model rather than loading incompatible ones.
        dropped_freqs = [key for key in list(ckpt) if key.endswith("freqs_cis")]
        for key in dropped_freqs:
            del ckpt[key]
        if dropped_freqs:
            print(
                f"Dropped {len(dropped_freqs)} resolution-specific freqs_cis buffer(s)."
            )

        missing_keys, unexpected_keys = video_model.load_state_dict(ckpt, strict=False)
        if strict_state_dict_loading:
            disallowed_missing = [
                key for key in missing_keys if key not in dropped_freqs
            ]
            if disallowed_missing or unexpected_keys:
                raise RuntimeError(
                    "Checkpoint is incompatible with the 3D model: "
                    f"missing keys={disallowed_missing}, "
                    f"unexpected keys={list(unexpected_keys)}"
                )
        if missing_keys:
            print(f"Missing keys: {missing_keys}")
        if unexpected_keys:
            print(f"Unexpected keys: {unexpected_keys}")

    model = video_model
    if training_mode:
        model = Sam3VideoTrainingModel(
            detector=video_model.detector, tracker=video_model.tracker
        )

    if training_mode and freeze_vision_backbone:
        for name, param in model.named_parameters():
            if (
                "backbone.vision_backbone" in name
                or "backbone.language_backbone" in name
            ):
                param.requires_grad = False

    if training_mode:
        trainable_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
        total_params = sum(p.numel() for p in model.parameters())
        print(
            f"Training Mode Enabled: Tunable parameters: "
            f"{trainable_params/1e6:.2f}M / {total_params/1e6:.2f}M"
        )

    model.to(device=device)
    return model


def build_sam3_video_predictor(*model_args, gpus_to_use=None, **model_kwargs):
    return Sam3VideoPredictorMultiGPU(
        *model_args, gpus_to_use=gpus_to_use, **model_kwargs
    )
