def unwrap_ddp_if_wrapped(model):
    if isinstance(model, torch.nn.parallel.DistributedDataParallel):
        return model.module
    return model


def _describe_non_finite_tensor(name, tensor):
    finite_mask = torch.isfinite(tensor)
    bad_mask = ~finite_mask
    bad_count = int(bad_mask.sum().item())
    nan_count = int(torch.isnan(tensor).sum().item())
    posinf_count = int((tensor == float("inf")).sum().item())
    neginf_count = int((tensor == float("-inf")).sum().item())
    finite_vals = tensor.detach()[finite_mask]
    if finite_vals.numel() > 0:
        finite_abs_max = float(finite_vals.float().abs().max().item())
    else:
        finite_abs_max = None
    return (
        f"{name} shape={tuple(tensor.shape)} bad_count={bad_count} "
        f"nan={nan_count} +inf={posinf_count} -inf={neginf_count} "
        f"finite_abs_max={finite_abs_max}"
    )


def _non_finite_tensor_summaries(named_tensors, patterns=None, limit=8):
    summaries = []
    for name, tensor in named_tensors:
        if tensor is None:
            continue
        if patterns is not None and not any(
            fnmatch.fnmatch(name, pattern) for pattern in patterns
        ):
            continue
        finite_mask = torch.isfinite(tensor)
        if not bool(finite_mask.all()):
            summaries.append(_describe_non_finite_tensor(name, tensor))
            if len(summaries) >= limit:
                break
    return summaries


