# Native module: utils/evaluate_model.py
_EMBEDDED_SOURCES['utils/evaluate_model.py'] = '''from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
import time
from typing import Protocol

import numpy as np
from PIL import Image, ImageOps
from tqdm import tqdm


SUPPORTED_IMAGE_SUFFIXES = {".bmp", ".jpeg", ".jpg", ".png", ".tif", ".tiff"}


@dataclass(frozen=True)
class DatasetLayout:
    root: Path
    images: Path
    masks: Path


@dataclass(frozen=True)
class SegmentationSample:
    sample_id: str
    image_path: Path
    mask_path: Path


class MedicalSAM3Predictor(Protocol):
    def encode_image(self, image: np.ndarray) -> dict: ...

    def predict_text(self, state: dict, text_prompt: str) -> np.ndarray | None: ...

    def predict_box(
        self,
        state: dict,
        bbox: tuple[int, int, int, int],
        image_size: tuple[int, int],
    ) -> np.ndarray | None: ...


def resolve_dataset_split(dataset_dir: Path, split: str) -> DatasetLayout:
    dataset_dir = Path(dataset_dir)
    if not dataset_dir.is_dir():
        raise FileNotFoundError(f"数据集目录不存在：{dataset_dir}")

    candidates: list[Path] = []
    direct = dataset_dir / split
    if (direct / "images").is_dir() and (direct / "masks").is_dir():
        candidates.append(direct)
    for candidate in dataset_dir.rglob(split):
        if candidate == direct or ".cache" in candidate.parts:
            continue
        if (candidate / "images").is_dir() and (candidate / "masks").is_dir():
            candidates.append(candidate)

    if not candidates:
        raise FileNotFoundError(
            f"在 {dataset_dir} 下找不到 {split}/images 和 {split}/masks"
        )
    if len(candidates) > 1:
        paths = ", ".join(str(path) for path in candidates)
        raise ValueError(f"发现多个 {split} 数据目录，无法确定使用哪一个：{paths}")

    root = candidates[0]
    return DatasetLayout(root=root, images=root / "images", masks=root / "masks")


def _image_files(path: Path, role: str, allow_empty: bool = False) -> list[Path]:
    if not Path(path).is_dir():
        raise FileNotFoundError(f"{role}目录不存在：{path}")
    files = [
        item
        for item in Path(path).iterdir()
        if item.is_file() and item.suffix.lower() in SUPPORTED_IMAGE_SUFFIXES
    ]
    if not files and not allow_empty:
        raise ValueError(f"{role}目录中没有支持的图像：{path}")
    return files


def _stem_sort_key(path: Path) -> tuple[int, int | str, str]:
    if path.stem.isdigit():
        return (0, int(path.stem), path.name.casefold())
    return (1, path.stem.casefold(), path.name.casefold())


def discover_samples(images_dir: Path, masks_dir: Path) -> list[SegmentationSample]:
    images = sorted(_image_files(images_dir, "图像"), key=_stem_sort_key)
    masks = _image_files(masks_dir, "掩膜", allow_empty=True)
    masks_by_stem: dict[str, Path] = {}
    for mask in masks:
        if mask.stem in masks_by_stem:
            raise ValueError(f"发现重复掩膜 stem：{mask.stem}")
        masks_by_stem[mask.stem] = mask

    missing = [image.name for image in images if image.stem not in masks_by_stem]
    if missing:
        raise ValueError(f"图像缺少对应掩膜：{missing[:10]}")

    image_stems = {image.stem for image in images}
    extra = [mask.name for mask in masks if mask.stem not in image_stems]
    if extra:
        raise ValueError(f"掩膜目录包含额外文件：{sorted(extra)[:10]}")

    return [
        SegmentationSample(
            sample_id=image.stem,
            image_path=image,
            mask_path=masks_by_stem[image.stem],
        )
        for image in images
    ]


def compute_binary_metrics(prediction: np.ndarray, target: np.ndarray) -> dict[str, float | int]:
    prediction = np.asarray(prediction, dtype=bool).squeeze()
    target = np.asarray(target, dtype=bool).squeeze()
    if prediction.shape != target.shape:
        raise ValueError(f"预测与 GT 尺寸不一致：{prediction.shape} != {target.shape}")

    intersection = int(np.logical_and(prediction, target).sum())
    prediction_pixels = int(prediction.sum())
    target_pixels = int(target.sum())
    union = prediction_pixels + target_pixels - intersection
    true_positive = intersection
    false_positive = prediction_pixels - intersection
    false_negative = target_pixels - intersection

    dice_denominator = prediction_pixels + target_pixels
    dice = 1.0 if dice_denominator == 0 else 2.0 * intersection / dice_denominator
    iou = 1.0 if union == 0 else intersection / union
    precision = (
        1.0 if true_positive + false_positive == 0 and target_pixels == 0
        else 0.0 if true_positive + false_positive == 0
        else true_positive / (true_positive + false_positive)
    )
    recall = (
        1.0 if true_positive + false_negative == 0
        else true_positive / (true_positive + false_negative)
    )
    return {
        "dice": float(dice),
        "iou": float(iou),
        "precision": float(precision),
        "recall": float(recall),
        "intersection": intersection,
        "prediction_pixels": prediction_pixels,
        "target_pixels": target_pixels,
        "union_pixels": union,
    }


def generate_bbox_from_mask(mask: np.ndarray) -> tuple[int, int, int, int] | None:
    mask = np.asarray(mask, dtype=bool).squeeze()
    if mask.ndim != 2:
        raise ValueError(f"GT 掩膜必须是二维数组，实际形状：{mask.shape}")
    y_indices, x_indices = np.where(mask)
    if not len(x_indices):
        return None
    return (
        int(x_indices.min()),
        int(y_indices.min()),
        int(x_indices.max()) + 1,
        int(y_indices.max()) + 1,
    )


def normalize_prediction(
    prediction: np.ndarray,
    target_shape: tuple[int, int],
) -> np.ndarray:
    prediction = np.asarray(prediction).squeeze()
    if prediction.ndim != 2:
        raise ValueError(f"预测掩膜必须是二维数组，实际形状：{prediction.shape}")
    binary = prediction.astype(bool)
    if binary.shape == target_shape:
        return binary
    resized = Image.fromarray(binary.astype(np.uint8) * 255).resize(
        (target_shape[1], target_shape[0]),
        resample=Image.Resampling.NEAREST,
    )
    return np.asarray(resized, dtype=np.uint8) > 127


def _load_rgb(path: Path) -> np.ndarray:
    with Image.open(path) as opened:
        return np.asarray(ImageOps.exif_transpose(opened).convert("RGB"))


def _load_binary_mask(path: Path) -> np.ndarray:
    with Image.open(path) as opened:
        return np.asarray(opened.convert("L"), dtype=np.uint8) > 127


def _save_prediction(
    image: np.ndarray,
    mask: np.ndarray,
    mask_path: Path,
    overlay_path: Path,
    color: tuple[int, int, int],
) -> None:
    mask_path.parent.mkdir(parents=True, exist_ok=True)
    overlay_path.parent.mkdir(parents=True, exist_ok=True)
    Image.fromarray(mask.astype(np.uint8) * 255, mode="L").save(mask_path)

    base = Image.fromarray(image.astype(np.uint8), mode="RGB").convert("RGBA")
    overlay = np.zeros((*mask.shape, 4), dtype=np.uint8)
    overlay[mask, :3] = color
    overlay[mask, 3] = 120
    composed = Image.alpha_composite(base, Image.fromarray(overlay, mode="RGBA"))
    composed.convert("RGB").save(overlay_path)


def _aggregate_metrics(rows: list[dict[str, object]]) -> dict[str, float | int | None]:
    if not rows:
        return {
            "sample_count": 0,
            "prediction_found_count": 0,
            "macro_dice": None,
            "macro_iou": None,
            "macro_precision": None,
            "macro_recall": None,
            "global_dice": None,
            "global_iou": None,
        }
    result: dict[str, float | int | None] = {
        "sample_count": len(rows),
        "prediction_found_count": sum(bool(row["prediction_found"]) for row in rows),
    }
    for name in ("dice", "iou", "precision", "recall"):
        result[f"macro_{name}"] = float(np.mean([float(row[name]) for row in rows]))
    intersection = sum(int(row["intersection"]) for row in rows)
    prediction_pixels = sum(int(row["prediction_pixels"]) for row in rows)
    target_pixels = sum(int(row["target_pixels"]) for row in rows)
    union_pixels = sum(int(row["union_pixels"]) for row in rows)
    denominator = prediction_pixels + target_pixels
    result["global_dice"] = 1.0 if denominator == 0 else 2.0 * intersection / denominator
    result["global_iou"] = 1.0 if union_pixels == 0 else intersection / union_pixels
    return result


def run_evaluation(
    samples: list[SegmentationSample],
    predictor: MedicalSAM3Predictor,
    result_dir: Path,
    mode: str,
    prompt_mode: str,
    text_prompt: str,
    limit: int | None,
) -> tuple[dict[str, object], dict[str, object]]:
    if mode not in {"single", "dataset"}:
        raise ValueError(f"不支持的运行模式：{mode}")
    if prompt_mode not in {"text", "gt-box", "both"}:
        raise ValueError(f"不支持的提示模式：{prompt_mode}")
    if not text_prompt.strip() and prompt_mode in {"text", "both"}:
        raise ValueError("文本提示不能为空")
    if limit is not None and limit <= 0:
        raise ValueError("limit 必须是正整数")
    if mode == "single" and limit is not None:
        raise ValueError("--limit 仅允许与 --mode dataset 一起使用")
    if not samples:
        raise ValueError("没有可运行的图像/掩膜样本")

    selected = samples[:1] if mode == "single" else samples[:limit]
    if prompt_mode == "both":
        prompt_names = ("text", "gt_box")
    else:
        prompt_names = (prompt_mode.replace("-", "_"),)
    prompt_metadata = {
        "text": {
            "source": "user_text",
            "oracle_assisted": False,
        },
        "gt_box": {
            "source": "ground_truth_mask_tight_bbox",
            "oracle_assisted": True,
        },
    }
    metric_rows: dict[str, list[dict[str, object]]] = {name: [] for name in prompt_names}
    sample_results: list[dict[str, object]] = []
    failures: list[dict[str, str]] = []
    result_dir = Path(result_dir)

    for sample in tqdm(selected, desc="Medical-SAM3", unit="image"):
        sample_started = time.perf_counter()
        predictions: dict[str, object] = {}
        try:
            image = _load_rgb(sample.image_path)
            target = _load_binary_mask(sample.mask_path)
            if image.shape[:2] != target.shape:
                raise ValueError(
                    f"图像与 GT 尺寸不一致：{image.shape[:2]} != {target.shape}"
                )
            state = predictor.encode_image(image)
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"
            failures.append(
                {
                    "sample_id": sample.sample_id,
                    "image_path": str(sample.image_path.resolve()),
                    "prompt": "sample_setup",
                    "error": error,
                }
            )
            sample_results.append(
                {
                    "sample_id": sample.sample_id,
                    "status": "failed",
                    "image_path": str(sample.image_path.resolve()),
                    "gt_path": str(sample.mask_path.resolve()),
                    "elapsed_ms": (time.perf_counter() - sample_started) * 1000.0,
                    "predictions": predictions,
                    "error": error,
                }
            )
            continue

        for prompt_name in prompt_names:
            try:
                inference_started = time.perf_counter()
                if prompt_name == "text":
                    raw_prediction = predictor.predict_text(state, text_prompt)
                    color = (239, 68, 68)
                    prompt_value: object = text_prompt
                else:
                    bbox = generate_bbox_from_mask(target)
                    if bbox is None:
                        raise ValueError(f"GT 掩膜为空，无法生成框提示：{sample.mask_path}")
                    raw_prediction = predictor.predict_box(state, bbox, target.shape)
                    color = (34, 211, 238)
                    prompt_value = list(bbox)
                inference_ms = (time.perf_counter() - inference_started) * 1000.0
                prediction_found = raw_prediction is not None
                prediction = (
                    np.zeros(target.shape, dtype=bool)
                    if raw_prediction is None
                    else normalize_prediction(raw_prediction, target.shape)
                )
                mask_path = result_dir / f"{prompt_name}_masks" / f"{sample.sample_id}.png"
                overlay_path = (
                    result_dir / f"{prompt_name}_overlays" / f"{sample.sample_id}.png"
                )
                _save_prediction(image, prediction, mask_path, overlay_path, color)
                row: dict[str, object] = {
                    "sample_id": sample.sample_id,
                    "prediction_found": prediction_found,
                    "inference_ms": inference_ms,
                    **compute_binary_metrics(prediction, target),
                }
                metric_rows[prompt_name].append(row)
                predictions[prompt_name] = {
                    "status": "success",
                    "prompt": prompt_value,
                    "prompt_source": prompt_metadata[prompt_name]["source"],
                    "oracle_assisted": prompt_metadata[prompt_name]["oracle_assisted"],
                    "prediction_found": prediction_found,
                    "mask_path": str(mask_path.resolve()),
                    "overlay_path": str(overlay_path.resolve()),
                    "inference_ms": inference_ms,
                }
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
                predictions[prompt_name] = {
                    "status": "failed",
                    "prompt_source": prompt_metadata[prompt_name]["source"],
                    "oracle_assisted": prompt_metadata[prompt_name]["oracle_assisted"],
                    "error": error,
                }
                failures.append(
                    {
                        "sample_id": sample.sample_id,
                        "image_path": str(sample.image_path.resolve()),
                        "prompt": prompt_name,
                        "error": error,
                    }
                )

        prompt_statuses = [
            str(predictions.get(name, {}).get("status", "failed"))
            for name in prompt_names
        ]
        if all(value == "success" for value in prompt_statuses):
            sample_status = "success"
        elif any(value == "success" for value in prompt_statuses):
            sample_status = "partial"
        else:
            sample_status = "failed"
        sample_results.append(
            {
                "sample_id": sample.sample_id,
                "status": sample_status,
                "image_path": str(sample.image_path.resolve()),
                "gt_path": str(sample.mask_path.resolve()),
                "elapsed_ms": (time.perf_counter() - sample_started) * 1000.0,
                "predictions": predictions,
            }
        )

    succeeded = sum(item["status"] == "success" for item in sample_results)
    partial = sum(item["status"] == "partial" for item in sample_results)
    failed = sum(item["status"] == "failed" for item in sample_results)
    status = "success" if succeeded == len(selected) else "partial" if succeeded or partial else "failed"
    successful_prompts = sum(
        prediction.get("status") == "success"
        for sample_result in sample_results
        for prediction in sample_result["predictions"].values()
    )
    requested_prompts = len(selected) * len(prompt_names)
    run_result: dict[str, object] = {
        "status": status,
        "mode": mode,
        "prompt_mode": prompt_mode,
        "prompt_metadata": {name: prompt_metadata[name] for name in prompt_names},
        "text_prompt": text_prompt if "text" in prompt_names else None,
        "available_sample_count": len(samples),
        "selected_sample_count": len(selected),
        "successful_sample_count": succeeded,
        "partial_sample_count": partial,
        "failed_sample_count": failed,
        "requested_prompt_count": requested_prompts,
        "successful_prompt_count": successful_prompts,
        "failed_prompt_count": requested_prompts - successful_prompts,
        "samples": sample_results,
        "failures": failures,
    }
    metrics: dict[str, object] = {
        prompt_name: _aggregate_metrics(rows)
        for prompt_name, rows in metric_rows.items()
    }
    metrics["prompt_metadata"] = {
        name: prompt_metadata[name] for name in prompt_names
    }
    metrics["per_sample"] = metric_rows
    return run_result, metrics
'''

